            elif tok == '*':
                stack.append(a * b)
            elif tok == '/':
                # int(a / b) truncates toward zero in Python 3
                stack.append(int(a / b))
            else:
                raise ValueError(f"Unsupported operator: {tok}")
    return stack[0] if stack else 0

