            elif token == '*':
                res = a * b
            else:  # division
                # Python division truncates toward negative infinity, so use int() on true division
                res = int(a / b)  # truncates toward zero
            stack.append(res)
        else:
            # parse integer, supports leading + or -
            stack.append(int(token))
    # After processing, stack should have exactly one element
    return stack[-1] if stack else 0

