def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Supports integer operands (including negatives) and the operators +, -, *, /.
    Division truncates toward zero, matching typical RPN calculator behavior.
    Returns the integer result; if tokens is empty, returns 0.
    """
    if not tokens:
        return 0
    stack = []
    ops = {'+', '-', '*', '/'}
    for token in tokens:
        if token in ops:
            # Pop the two most recent operands
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            # Operand
            stack.append(int(token))
    # After processing, there should be exactly one value on the stack
    return stack[0] if stack else 0

