def solve(grid):
    """Count islands using BFS, handling jagged rows.
    Returns number of 4-directionally connected components of 1s.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False]*len(row) for row in grid ]
    from collections import deque
    def bfs(r, c):
        dq = deque([(r, c)])
        while dq:
            i, j = dq.popleft()
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if visited[i][j] or grid[i][j] == 0:
                continue
            visited[i][j] = True
            dq.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if not visited[i][j] and grid[i][j] == 1:
                bfs(i, j)
                count += 1
    return count

